"""Safe execution sandbox for Python code generated by LLM.
Executes code against business DataFrames, captures `result`, and handles exceptions.
"""

import ast
import concurrent.futures
import datetime
from datetime import date, timedelta
import traceback
from typing import Any, Dict, Optional, Tuple
import numpy as np
import pandas as pd


FORBIDDEN_MODULES = {
    "os", "sys", "subprocess", "socket", "urllib", "requests",
    "shutil", "builtins", "importlib", "pathlib", "fcntl", "pty"
}

FORBIDDEN_CALLS = {
    "eval", "exec", "compile", "__import__", "open", "input"
}


def is_safe_code(code_str: str) -> Tuple[bool, Optional[str]]:
    """AST check to ensure code does not import dangerous modules or call dangerous builtins."""
    try:
        tree = ast.parse(code_str)
    except SyntaxError as e:
        return False, f"SyntaxError: {e}"

    for node in ast.walk(tree):
        # Check imports
        if isinstance(node, ast.Import):
            for alias in node.names:
                mod = alias.name.split(".")[0]
                if mod in FORBIDDEN_MODULES:
                    return False, f"Forbidden import: {alias.name}"
        elif isinstance(node, ast.ImportFrom):
            if node.module:
                mod = node.module.split(".")[0]
                if mod in FORBIDDEN_MODULES:
                    return False, f"Forbidden import: {node.module}"
        # Check forbidden function calls
        elif isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                if node.func.id in FORBIDDEN_CALLS:
                    return False, f"Forbidden function call: {node.func.id}"

    return True, None


def _run_exec(code: str, exec_env: Dict[str, Any]) -> Any:
    # Execute code in pre-populated environment
    exec(code, exec_env)
    return exec_env.get("result", None)


def execute_code(
    code: str,
    data: Dict[str, pd.DataFrame],
    context: Optional[Dict[str, Any]] = None,
    timeout: int = 30
) -> Tuple[Any, Optional[str]]:
    """Execute Python code against business data.
    Returns:
      (result, None) if successful
      (None, error_str) if failed or timed out
    """
    is_safe, reason = is_safe_code(code)
    if not is_safe:
        return None, f"Security Violation: {reason}"

    # Build execution environment
    ctx = context or {}
    exec_env: Dict[str, Any] = {
        "data": data,
        "pd": pd,
        "np": np,
        "datetime": datetime.datetime,
        "date": date,
        "timedelta": timedelta,
        "result": None,
        "as_of_date": ctx.get("as_of_date", ""),
        "calendar": ctx.get("calendar", None),
        "unit_conversion": ctx.get("unit_conversion", None),
    }

    # Execute with timeout
    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
        future = executor.submit(_run_exec, code, exec_env)
        try:
            res = future.result(timeout=timeout)
            return res, None
        except concurrent.futures.TimeoutError:
            return None, f"Execution timed out after {timeout} seconds"
        except Exception as e:
            tb = traceback.format_exc()
            return None, f"Execution Error: {e}\n{tb}"
